NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Ephesians'

CHAPTERS = {
    1: {
        1: 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, pyhille, jotka ovat Efesossa, ja uskoville Kristuksessa Jeesuksessa.',
        2: 'Armo teille ja rauha Jumalalta, Isältämme, ja Herralta Jeesukselta Kristukselta!',
        3: 'Ylistetty olkoon Herramme Jeesuksen Kristuksen Jumala ja Isä, joka on siunannut meitä kaikella hengellisellä siunauksella taivaallisissa Kristuksessa,',
        4: 'niin kuin hän ennen maailman perustamista oli hänessä valinnut meidät olemaan pyhiä ja moitteettomia hänen edessään, rakkaudessa,',
        5: 'edeltä määräten meidät lapseuteen hänelle itselleen Jeesuksen Kristuksen kautta, hänen oman tahtonsa mielisuosion mukaan,',
        6: 'sen armonsa kirkkauden kiitokseksi, jonka hän on lahjoittanut meille siinä rakastetussa,',
        7: 'jossa meillä on lunastus hänen verensä kautta, rikkomisten anteeksisaaminen hänen armonsa rikkauden mukaan,',
        8: 'jota hän on antanut ylenpalttisesti meitä varten suodakseen kaikkea viisautta ja ymmärrystä,',
        9: 'tehden meille tiettäväksi tahtonsa salaisuuden mielisuosionsa mukaan, jonka hän oli säätänyt edeltä itsessään toteutuvaksi,',
        10: 'että hän aikojen täytyttyä tapahtuvaa armotaloutta varten yhdistäisi Kristuksessa yhdeksi kaikki, mikä on taivaissa ja mikä maan päällä.',
        11: 'Hänessä myös olemme saaneet perintöosan, ollen siihen edeltä määrätyt hänen suunnitelmansa mukaan, hänen, joka vaikuttaa kaiken oman tahtonsa ja päätöksensä mukaan,',
        12: 'että me olisimme hänen kirkkautensa kiitokseksi, me, jotka jo edeltä olimme panneet toivomme Kristukseen.',
        13: 'Hänessä on teihinkin, sitten kun olitte kuulleet totuuden sanan, pelastuksenne evankeliumin, uskoviksi tultuanne pantu luvatun Pyhän Hengen sinetti,',
        14: 'sen, joka on meidän perintömme vakuutena, hänen omaisuutensa lunastamista varten hänen kirkkautensa kiitokseksi.',
        15: 'Sen tähden, kun kuulin siitä uskosta, joka teillä on Herraan Jeesukseen, ja teidän rakkaudestanne kaikkia pyhiä kohtaan,',
        16: 'minäkään en lakkaa kiittämästä teidän tähtenne, kun muistelen teitä rukouksissani,',
        17: 'anoen, että meidän Herramme Jeesuksen Kristuksen Jumala, kirkkauden Isä, antaisi teille viisauden ja ilmoituksen Hengen hänen tuntemisessaan',
        18: 'ja valaisisi teidän sydämenne silmät, että tietäisitte, mikä on se toivo, johon hän on teidät kutsunut, kuinka suuri hänen perintönsä kirkkauden runsaus hänen pyhissään',
        19: 'ja mikä hänen voimansa ylenpalttinen suuruus meitä uskovia kohtaan sen hänen väkevyytensä voiman vaikutuksen mukaan,',
        20: 'jonka hän vaikutti Kristuksessa, kun hän herätti hänet kuolleista ja asetti hänet istumaan oikealle puolelleen taivaissa,',
        21: 'korkeammalle kaikkea hallitusta, valtaa, voimaa, herruutta ja jokaista nimeä, mikä mainitaan, ei ainoastaan tässä maailmanajassa, vaan myös tulevassa.',
        22: 'Kaiken hän on asettanut hänen jalkojensa alle ja antanut hänet kaiken pääksi seurakunnassa,',
        23: 'joka on hänen ruumiinsa, sen täyteys, joka kaiken kaikessa täyttää.',
    },
    2: {
        1: 'Jumala on eläviksi tehnyt teidät, jotka olitte kuolleet rikoksiinne ja synteihinne,',
        2: 'joissa te ennen vaelsitte tämän maailman menon mukaan, ilmapiirin hallitsijan, sen hengen hallitsijan, mukaan, joka nyt tekee työtään epäuskon lapsissa,',
        3: 'joiden joukossa mekin kaikki ennen vaelsimme lihamme himoissa, noudattaen lihan ja järjen tahtoa, ja olimme luonnostamme vihan lapsia kuten muutkin,',
        4: 'mutta Jumala, joka on laupeudesta rikas, suuren rakkautensa tähden, jolla hän on meitä rakastanut,',
        5: 'on tehnyt meidät, jotka olimme kuolleet rikoksiimme, eläviksi Kristuksen kanssa – armosta te olette pelastetut –',
        6: 'ja yhdessä hänen kanssaan herättänyt ja yhdessä hänen kanssaan asettanut meidät taivaallisiin Kristuksessa Jeesuksessa,',
        7: 'osoittaakseen tulevina maailmanaikoina armonsa ylenpalttista runsautta, hyvyydessään meitä kohtaan Kristuksessa Jeesuksessa.',
        8: 'Sillä armosta te olette pelastetut uskon kautta. Se ei ole teistä. Se on Jumalan lahja.',
        9: 'Se ei ole teoista, ettei kukaan kerskaisi.',
        10: 'Sillä olemme hänen tekonsa, luodut Kristuksessa Jeesuksessa hyviä töitä varten, jotka Jumala on edeltäpäin valmistanut, jotta niissä vaeltaisimme.',
        11: 'Muistakaa sen tähden, että te ennen, te lihanne puolesta pakanat, jotka olette saaneet ympärileikkaamattomien nimen niiltä, joita lihaan käsillä tehdyn ympärileikkauksen mukaisesti sanotaan ympärileikatuiksi –',
        12: 'että te siihen aikaan olitte ilman Kristusta, olitte vailla Israelin kansalaisoikeutta ja vieraat lupauksen liitoille, ilman toivoa ja ilman Jumalaa maailmassa.',
        13: 'Mutta nyt, kun olette Kristuksessa Jeesuksessa, olette te, jotka ennen olitte kaukana, tulleet lähelle Kristuksen veressä.',
        14: 'Sillä hän on meidän rauhamme, hän, joka teki molemmat yhdeksi ja purki erottavan väliseinän, nimittäin vihollisuuden,',
        15: 'kun hän lihassaan teki tehottomaksi käskyjen lain säädöksineen, luodakseen itsessään nuo kaksi yhdeksi uudeksi ihmiseksi, tehden rauhan,',
        16: 'ja yhdessä ruumiissa sovittaakseen molemmat Jumalan kanssa ristin kautta kuolettaen itsessään vihollisuuden.',
        17: 'Ja hän tuli ja julisti rauhaa teille, jotka olitte kaukana, ja rauhaa niille, jotka olitte lähellä,',
        18: 'sillä hänen kauttaan meillä molemmilla on pääsy yhdessä Hengessä Isän luo.',
        19: 'Niin ette siis enää ole vieraita ettekä muukalaisia, vaan olette pyhien kansalaisia ja Jumalan perheväkeä,',
        20: 'apostolien ja profeettojen perustukselle rakennettuja, kulmakivenä itse Kristus Jeesus,',
        21: 'jossa koko rakennus liittyy yhteen ja kasvaa pyhäksi temppeliksi Herrassa,',
        22: 'ja hänessä tekin yhdessä muitten kanssa rakennutte Jumalan asumukseksi Hengessä.',
    },
    3: {
        1: 'Sen takia minä, Paavali, teidän, pakanoiden, tähden Kristuksen Jeesuksen vanki, notkistan polveni –',
        2: 'olettehan kuulleet siitä Jumalan armon taloudenhoidosta, mikä on minulle annettu teitä varten,',
        3: 'että näet tämä salaisuus on ilmoituksen kautta tehty minulle tiettäväksi, niin kuin olen siitä edellä lyhyesti kirjoittanut,',
        4: 'josta te sitä lukiessanne voitte havaita perehtyneisyyteni Kristuksen salaisuuteen,',
        5: 'jota muiden sukupolvien aikana ei ole ihmisten lapsille tiettäväksi tehty, niin kuin se nyt on ilmoitettu Hengessä hänen pyhille apostoleilleen ja profeetoille:',
        6: 'että näet pakanatkin ovat kanssaperillisiä ja yhtä ruumista ja osallisia lupaukseen Kristuksessa Jeesuksessa evankeliumin kautta,',
        7: 'jonka palvelijaksi olen tullut Jumalan armon lahjan kautta, joka minulle on annettu hänen voimansa vaikutuksesta.',
        8: 'Minulle, kaikista pyhistä halvimmalle, on annettu tämä armo: julistaa pakanoiden keskuudessa evankeliumia Kristuksen tutkimattomasta rikkaudesta',
        9: 'ja tehdä kaikille selväksi, mitä on sen salaisuuden taloudenhoito, joka ikuisista ajoista asti on ollut kätkettynä Jumalassa, joka on kaiken luonut Jeesuksen Kristuksen kautta,',
        10: 'että Jumalan moninainen viisaus seurakunnan kautta nyt tulisi taivaallisten hallitusten ja valtojen tietoon',
        11: 'sen iankaikkisen päätöksen mukaisesti, jonka hän oli säätänyt Kristuksessa Jeesuksessa, meidän Herrassamme,',
        12: 'jossa meillä uskon kautta häneen on rohkeus ja oikeus lähestyä häntä luottamuksella.',
        13: 'Siksi pyydän, ettette lannistuisi niiden ahdistusten vuoksi, joita minulla on teidän tähtenne. Ne ovat teidän kunnianne.',
        14: 'Sen tähden notkistan polveni Herramme Jeesuksen Kristuksen Isän edessä,',
        15: 'josta kaikki, millä isä on, taivaissa ja maan päällä, saa nimensä,',
        16: 'että hän kirkkautensa runsauden mukaisesti antaisi teidän, sisäisen ihmisenne puolesta, voimassa vahvistua Henkensä kautta',
        17: 'ja Kristuksen asua uskon kautta teidän sydämissänne,',
        18: 'jotta rakkauteen juurtuneina ja perustuneina voisitte kaikkien pyhien kanssa käsittää, mikä leveys, pituus, korkeus ja syvyys on,',
        19: 'ja oppia tuntemaan Kristuksen rakkauden, joka ylittää kaiken tiedon, että tulisitte täyteen Jumalan kaikkea täyteyttä.',
        20: 'Mutta hänelle, joka voi tehdä enemmän, monin verroin enemmän kuin kaikki, mitä anomme tai ymmärrämme, sen voiman mukaan, joka meissä vaikuttaa,',
        21: 'hänelle kunnia seurakunnassa ja Kristuksessa Jeesuksessa kautta kaikkien sukupolvien, iankaikkisuuden iankaikkisuuksiin! Aamen.',
    },
    4: {
        1: 'Kehotan siis minä, vanki Herrassa, teitä vaeltamaan kutsumuksenne arvon mukaisesti,',
        2: 'kaikessa nöyryydessä ja lempeydessä pitkämielisesti sietäen toinen toistanne rakkaudessa',
        3: 'ja pyrkien säilyttämään hengen yhteyden rauhan yhdyssiteellä:',
        4: 'yksi ruumis ja yksi henki, kuten olette kutsututkin yhteen ja samaan kutsumuksenne antamaan toivoon;',
        5: 'yksi Herra, yksi usko, yksi kaste;',
        6: 'yksi Jumala ja kaikkien Isä, joka on yli kaikkien, kaikkien kautta ja kaikissa teissä.',
        7: 'Mutta itse kullekin meistä on armo annettu Kristuksen lahjan mitan mukaan.',
        8: 'Sen tähden on sanottu: "Hän astui ylös korkeuteen, hän otti vankeja saaliikseen, hän antoi lahjoja ihmisille."',
        9: 'Mutta että hän astui ylös, mitä se on muuta, kuin että hän oli astunut alaskin, maan alimpiin paikkoihin?',
        10: 'Hän, joka on astunut alas, on se, joka myös astui ylös, kaikkia taivaita ylemmäksi, täyttääkseen kaiken.',
        11: 'Ja hän antoi muutamat apostoleiksi, toiset profeetoiksi, toiset evankelistoiksi, mutta toiset paimeniksi ja opettajiksi,',
        12: 'varustaakseen pyhät palveluksen työhön, Kristuksen ruumiin rakentamiseen,',
        13: 'kunnes kaikki pääsemme uskon yhteyteen ja Jumalan Pojan tuntemiseen, täydelliseksi mieheksi, Kristuksen täyteyden täysi-ikäisyyden määrään,',
        14: 'ettemme enää olisi alaikäisiä, jotka ajelehtivat ja joita viskellään kaikissa opintuulissa ja ihmisten arpapelissä ja eksytyksen kavalissa juonissa,',
        15: 'vaan että totuutta noudattaen rakkaudessa kaikessa kasvaisimme häneen, joka on pää, Kristus,',
        16: 'josta koko ruumis yhteen liitettynä ja koossa pysyen jokaisen jänteensä avulla kasvaa rakentuakseen rakkaudessa sen voiman määrän mukaan, mikä kullakin osalla on.',
        17: 'Sen siis sanon ja todistan Herrassa: älkää enää vaeltako, niin kuin muut pakanat vaeltavat mielensä turhuudessa,',
        18: 'nuo, jotka pimentyneinä ymmärrykseltään ja vieraantuneina Jumalan elämästä heissä olevan tietämättömyyden tähden ja sydämensä paatumuksen tähden',
        19: 'ovat tuntonsa paaduttaneet ja heittäytyneet irstauden valtaan harjoittamaan kaikenlaista saastaisuutta ahneudessa.',
        20: 'Mutta näin te ette ole oppineet Kristusta tuntemaan,',
        21: 'jos muuten olette hänestä kuulleet ja hänessä opetusta saaneet, niin kuin totuus on Jeesuksessa:',
        22: 'että teidän tulee panna pois vanha ihmisenne, jonka mukaan ennen vaelsitte ja joka turmelee itsensä petollisia himoja seuraten,',
        23: 'ja uudistua mielenne hengeltä',
        24: 'ja pukea päällenne uusi ihminen, joka Jumalan mukaan on luotu totuuden vanhurskauteen ja pyhyyteen.',
        25: 'Pankaa sen tähden pois valhe ja puhukaa totta, kukin lähimmäisensä kanssa, sillä olemme toistemme jäseniä.',
        26: '"Vihastukaa, mutta älkää syntiä tehkö." Älkää antako auringon laskea vihanne yli,',
        27: 'älkääkä antako perkeleelle sijaa.',
        28: 'Joka on varastanut, älköön enää varastako, vaan tehköön ennemmin työtä ja toimittakoon käsillään sitä, mikä hyvää on, että hänellä olisi, mitä antaa tarvitsevalle.',
        29: 'Mikään sopimaton puhe älköön lähtekö suustanne, vaan ainoastaan sellainen, mikä rakentaa ja on tarpeellista sekä mieluista niille, jotka kuulevat.',
        30: 'Älkääkä saattako murheelliseksi Jumalan Pyhää Henkeä, jolla teidät on sinetöity lunastuksen päivään asti.',
        31: 'Kaikki katkeruus, kiivastus, viha, huuto ja pilkka sekä kaikki pahuus olkoon kaukana teistä.',
        32: 'Olkaa sen sijaan toisianne kohtaan ystävällisiä, hyväsydämisiä, anteeksiantavaisia toinen toisellenne, niin kuin Jumalakin on Kristuksessa teille antanut anteeksi.',
    },
    5: {
        1: 'Olkaa siis Jumalan seuraajia, niin kuin rakkaat lapset,',
        2: 'ja vaeltakaa rakkaudessa, niin kuin Kristuskin rakasti teitä ja antoi itsensä meidän edestämme lahjaksi ja uhriksi, Jumalalle "suloiseksi tuoksuksi".',
        3: 'Mutta haureutta eikä minkäänlaista saastaisuutta tai ahneutta älköön edes mainittako keskuudessanne – niin kuin pyhille sopii –',
        4: 'älköön myöskään rivoutta, tyhmyyksiä tai ilvehtimistä, jotka ovat sopimattomia, vaan pikemminkin kiitosta.',
        5: 'Sillä sen te tiedätte ja tunnette, ettei yhdelläkään haureellisella eikä saastaisella eikä ahneella – sillä hän on epäjumalanpalvelija – ole perintöosaa Kristuksen ja Jumalan valtakunnassa.',
        6: 'Älköön kukaan pettäkö teitä tyhjillä puheilla, sillä niiden tähden Jumalan viha tulee tottelemattomuuden lasten päälle.',
        7: 'Älkää siis olko niihin osallisia heidän kanssaan.',
        8: 'Ennen te olitte pimeys, mutta nyt olette valkeus Herrassa. Vaeltakaa valkeuden lapsina',
        9: '– sillä kaikki hyvyys, vanhurskaus ja totuus on Hengen hedelmää –',
        10: 'ja tutkikaa, mikä on otollista Herralle.',
        11: 'Älkää myöskään olko osallisia pimeyden hedelmättömiin tekoihin, vaan päinvastoin nuhdelkaakin niistä.',
        12: 'Sillä häpeällistä on sanoakin, mitä he salassa tekevät.',
        13: 'Mutta tämä kaikki tulee ilmi, kun valkeus siitä nuhtelee, sillä kaikki, mikä tulee ilmi, on valkeutta.',
        14: 'Sen tähden sanotaan: "Herää sinä, joka nukut, ja nouse kuolleista, niin Kristus sinua valaisee!"',
        15: 'Katsokaa siis tarkoin, kuinka vaellatte: ei niin kuin tyhmät, vaan niin kuin viisaat,',
        16: 'ja ottakaa vaari oikeasta hetkestä, sillä aika on paha.',
        17: 'Älkää sen tähden olko tyhmiä, vaan ymmärtäkää, mikä Herran tahto on.',
        18: 'Älkääkä juopuko viinistä, sillä siitä tulee paha meno, vaan täyttykää Hengellä,',
        19: 'puhuen keskenänne psalmeilla, kiitosvirsillä ja hengellisillä lauluilla veisaten ja laulaen sydämessänne Herralle,',
        20: 'kiittäen aina Jumalaa ja Isää kaikesta meidän Herramme Jeesuksen Kristuksen nimessä.',
        21: 'Ja olkaa toinen toisellenne alamaisia Kristuksen pelossa.',
        22: 'Vaimot, olkaa kukin omalle miehellenne alamaisia niin kuin Herralle,',
        23: 'sillä mies on vaimon pää, niin kuin myös Kristus on seurakunnan pää, hän, ruumiin vapahtaja.',
        24: 'Mutta niin kuin seurakunta on Kristukselle alamainen, samoin olkoot vaimotkin kukin miehelleen kaikessa alamaiset.',
        25: 'Miehet, rakastakaa vaimoanne, niin kuin Kristuskin rakasti seurakuntaa ja antoi itsensä alttiiksi sen edestä,',
        26: 'että hän sen pyhittäisi puhdistaen sen vesipesussa sanalla',
        27: 'saadakseen asetetuksi eteensä kirkastettuna seurakunnan, jossa ei olisi tahraa eikä ryppyä eikä mitään muuta sellaista, vaan joka olisi pyhä ja nuhteeton.',
        28: 'Samalla tavoin tulee myös miesten rakastaa vaimoaan kuin omaa ruumistaan. Se, joka rakastaa vaimoaan, rakastaa itseään.',
        29: 'Sillä eihän kukaan koskaan ole vihannut omaa lihaansa, vaan hän ravitsee ja vaalii sitä, niin kuin Kristuskin seurakuntaa,',
        30: 'sillä me olemme hänen ruumiinsa jäseniä hänen lihastaan ja hänen luistaan.',
        31: '"Sen tähden mies luopukoon isästään ja äidistään ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi."',
        32: 'Tämä salaisuus on suuri. Mutta minä tarkoitan Kristusta ja seurakuntaa.',
        33: 'Mutta myös teistä kukin kohdaltaan rakastakoon vaimoaan samoin kuin itseään, mutta vaimo pelätköön miestään.',
    },
    6: {
        1: 'Lapset, olkaa vanhemmillenne kuuliaiset Herrassa, sillä se on oikein.',
        2: '"Kunnioita isääsi ja äitiäsi." Tämä on ensimmäinen käsky, jolla on lupaus:',
        3: '"että menestyisit ja kauan eläisit maan päällä."',
        4: 'Ja te isät, älkää kiihottako lapsianne vihaan, vaan kasvattakaa heidät Herran opetuksessa ja nuhteessa.',
        5: 'Palvelijat, olkaa kuuliaisia maallisille isännillenne pelolla ja vavisten sydämenne yksinkertaisuudessa kuin Kristukselle,',
        6: 'ei silmänpalvelijoina, ihmisille mieliksi, vaan Kristuksen palvelijoina, sydämestänne tehden Jumalan tahdon,',
        7: 'hyvillä mielin, kuin palvelisitte Herraa ettekä ihmisiä,',
        8: 'tietäen, että mitä hyvää kukin tekee, hän saa siitä palkan Herralta, olkoon orja tai vapaa.',
        9: 'Ja te isännät, tehkää samoin heille, jättäkää pois uhkailu, sillä tiedättehän, että sekä heidän että teidän Herranne on taivaissa ja ettei hän katso henkilöön.',
        10: 'Lopuksi, vahvistukaa Herrassa ja hänen väkevyytensä voimassa.',
        11: 'Pukekaa yllenne Jumalan koko sota-asu voidaksenne kestää perkeleen kavalat juonet.',
        12: 'Sillä meillä ei ole taistelu verta ja lihaa vastaan, vaan hallituksia vastaan, valtoja vastaan, tässä pimeydessä hallitsevia maailmanvaltiaita vastaan, pahuuden henkiolentoja vastaan taivaan avaruuksissa.',
        13: 'Sen tähden ottakaa päällenne Jumalan koko sota-asu voidaksenne pahana päivänä tehdä vastarintaa ja kaiken suoritettuanne pysyä pystyssä.',
        14: 'Seisokaa siis lanteet totuuteen vyötettyinä, ja olkoon pukunanne vanhurskauden haarniska,',
        15: 'ja kenkinä jaloissanne alttius rauhan evankeliumille.',
        16: 'Kaikessa ottakaa uskon kilpi, jolla voitte sammuttaa kaikki pahan palavat nuolet,',
        17: 'ja ottakaa vastaan pelastuksen kypärä ja Hengen miekka, joka on Jumalan sana.',
        18: 'Ja tehkää tämä kaikella rukouksella ja anomisella rukoillen kaiken aikaa Hengessä ja sitä varten valvoen kaikessa kestävyydessä ja anomisessa kaikkien pyhien puolesta,',
        19: 'ja minunkin puolestani, että minulle, kun suuni avaan, annettaisiin sana rohkeasti julistaakseni evankeliumin salaisuutta,',
        20: 'jonka tähden olen lähettiläänä kahleissa, että puhuisin rohkeasti hänessä, niin kuin minun tulee puhua.',
        21: 'Mutta että tekin tietäisitte, kuinka minun on ja mitä teen, niin Tykikus, rakas veljeni ja uskollinen palvelija Herrassa, antaa teille siitä kaikesta tiedon.',
        22: 'Lähetän hänet luoksenne juuri sitä varten, että saisitte tietää tilamme ja että hän lohduttaisi sydämiänne.',
        23: 'Rauha veljille ja rakkaus, uskon kanssa, Isältä Jumalalta ja Herralta Jeesukselta Kristukselta!',
        24: 'Armo olkoon kaikkien kanssa, jotka rakastavat meidän Herraamme Jeesusta Kristusta katoamattomuudessa.',
    },
}
